  --space-sm: calc(0.5rem * var(--density));
  --space-md: calc(1rem * var(--density));
  --space-lg: calc(1.5rem * var(--density));
  --space-xl: calc(2rem * var(--density));
  --space-2xl: calc(3rem * var(--density));
  --shadow: 0 1px 3px rgb(0 0 0 / 0.3), 0 1px 2px rgb(0 0 0 / 0.2);
  --duration-fast: 100ms;
  --duration-normal: 200ms;
  --duration-slow: 400ms;

  --radius: 0.125rem;
  --radius-sm: calc(var(--radius) * 0.5);
  --radius-md: var(--radius);
  --radius-lg: calc(var(--radius) * 1.5);
  --radius-xl: calc(var(--radius) * 2);

  --content-max-width: 80rem;
  --scroll-padding-top: 5.25rem;
  --density: 1;
  --motion-speed: 1;
  --space-section: calc(4rem * var(--density));
  --easing: cubic-bezier(0.4, 0, 0.2, 1);

  --btn-bg: var(--color-text);
  --btn-border: none;
  --btn-text-color: var(--color-background);
  --btn-padding: 0.25rem 1rem;
  --btn-radius: var(--radius);
  --btn-transform: none;
  --btn-icon-display: none;

  --heading-weight: 400;
  --heading-size: 64px;
  --heading-letter-spacing: -0.025em;
  --heading-transform: none;
  --heading-font-style: normal;
  --body-size: 16px;
  --body-weight: 400;
  --body-line-height: 1.6;

  --img-shadow: 0 8px 30px rgb(0 0 0 / 0.4);
  --img-radius: var(--radius);

  --animate-icon-bounce: icon-bounce 450ms ease-out;
}

:root {
  --font-heading: var(--font-matter), "Matter", system-ui, sans-serif;
  --font-display: var(--font-matter), "Inter", "Inter Fallback", system-ui, sans-serif;
}

html {
  scroll-padding-top: var(--scroll-padding-top);
}

body {
  background-color: var(--color-background);
  color: var(--color-text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

@layer base {
  h1, h2, h3 {
    text-transform: var(--heading-transform);
    font-style: var(--heading-font-style);
  }
}

.font-display {
  font-family: var(--font-display);
}

/* warp.dev applies uppercase + tracking to the mono utility globally;
   doubled selector avoids Tailwind de-duping it against the generated .font-mono */
.font-mono.font-mono {
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* FAQ answer reveal: fade + 6px slide-down on open (display:none -> flex via [hidden]) */
.faq-answer {
  transition: opacity 0.2s, translate 0.2s;
}

@starting-style {
  .faq-answer:not([hidden]) {
    opacity: 0;
    translate: 0 -6px;
  }
}

.animate-scroll-left {
  animation: scroll-left var(--scroll-duration, 40s) linear infinite;
}

.animate-hero-carousel {
  animation: hero-left-photo-carousel 8s infinite;
}

#testimonials {
  --testimonial-bg: var(--color-accent-purple);
  --testimonial-fg: var(--color-background);
  --testimonial-muted: color-mix(in oklch, var(--color-background) 65%, transparent);
}

.theme-invert {
  --color-surface: #fff;
  --color-text: #0a0907;
  --color-text-body: #3c3a38;
  --color-text-secondary: #5f5d59;
  --color-border: lab(88.42% 0.148237 1.90103);
  --card-bg: #fff;
}

@media (color-gamut: p3) {
  .theme-invert {
    --color-text: lab(2.48527% 0.0667796 0.668094);
    --color-text-body: lab(24.6193% 0.160992 1.90949);
    --color-text-secondary: lab(39.7069% 0.226021 2.6737);
  }
}

